import "../Styles/CompanyRegister.css";
import Header from "./Header";
import Footer from "./Footer";
import { Link } from "react-router-dom";

const CompanyRegister = () => {
  return (
    <div className="company-register-page">
      <Header />

      <section className="company-register-section">
        <div className="register-box">
          <h2 className="register-title">
            Create your <span>company account</span>
          </h2>
          <p className="register-subtitle">
            Please fill in your company details below to create an account.
          </p>

          <form className="register-form">
            <label>Company Name</label>
            <input type="text" placeholder="Example Company" required />

            <label>Email</label>
            <input type="email" placeholder="company@example.com" required />

            <label>Password</label>
            <input type="password" placeholder="************" required />

            <button type="submit" className="signup-btn">
              Sign up
            </button>
          </form>

          <p className="login-text">
            Already have an account?{" "}
            <Link to="/companylogin" className="login-link">
              Log in now!
            </Link>
          </p>
        </div>
      </section>

      <Footer />
    </div>
  );
};

export default CompanyRegister;
